import re
from pathlib import Path
name='1982_10'
path=Path(f'/mnt/data/LSF/data/officeqa/text/treasury_bulletin_{name}.txt')
lines=path.read_text(errors='ignore').splitlines()
# find MS-1 heading with per capita nearby
heading=None
for idx,line in enumerate(lines):
    if 'MS-1' in line:
        if any('per capita' in (lines[j].lower()) for j in range(idx,min(len(lines),idx+220))):
            heading=idx
print('heading', heading+1 if heading is not None else None)
pat=re.compile(r'"'^'"\\s*\\"'$?'"\\d[\\d,.,\\s]*\\s*"'$'"')
if heading is not None:
    for i in range(heading, min(len(lines), heading+700)):
        t=lines[i].strip().replace('"'$'"','')
        if pat.match(t) and '.' in t:
            print(i+1, repr(lines[i]))
